unbCatLeft : {X : Set o} → Category (suc o) (suc ℓ) (suc e) ≅ Unb-Cat X ℓ e
unbCatLeft {o = o} = record
  { from = λ C → record { Obj = X ; UC }
  ; to   = λ uc → record { Obj = X ; UC }
  -- this is cheating, but it is the only way to prove the left side of the equivalence type
  -- because we cannot prove that there are no non-trivial parallel arrows between distinct singletons
  ; iso = mkIso (λ _ → refl) λ _ → refl
  }

